// Printing a chart sheet: one page, the chart fitted to what the margins
// leave of the paper. Every workbook is generated by code.
//
// Excel is not at hand: what follows its known behaviour without having been
// compared with it is marked UNSURE.

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { open, type Workbook } from '../src/index';
import { createSheetMetrics } from '../src/layout/sheet-metrics';
import { DocumentPrintError } from '../src/ui/doc-print';
import { paintSheetPage, planSheetPages } from '../src/ui/sheet-print';
import { catAx, chartWorkbook, chartXml, group, numRef, ser, sheetData, solid, spPr, strRef, title, valAx } from './chart-fixtures';

/** Records what is drawn, in pixels of the canvas: translations and scales are applied, turns are not. */
class RecordingContext {
  fillStyle = '#000000';
  strokeStyle = '#000000';
  lineWidth = 1;
  globalAlpha = 1;
  textAlign = 'left';
  textBaseline = 'alphabetic';
  lineCap = 'butt';
  lineJoin = 'miter';
  font = '10px sans-serif';
  rects: { x: number; y: number; width: number; height: number; fill: string }[] = [];
  texts: { text: string; x: number; y: number; scale: number }[] = [];
  clips: { x: number; y: number; width: number; height: number }[] = [];
  private matrix = [1, 0, 0, 1, 0, 0];
  private stack: number[][] = [];
  private pending: { x: number; y: number; width: number; height: number }[] = [];
  save(): void {
    this.stack.push(this.matrix.slice());
  }
  restore(): void {
    const matrix = this.stack.pop();
    assert.ok(matrix, 'restore() without save()');
    this.matrix = matrix;
  }
  setTransform(a: number, _b: number, _c: number, d: number, e: number, f: number): void {
    this.matrix = [a, 0, 0, d, e, f];
  }
  translate(x: number, y: number): void {
    this.matrix[4] += this.matrix[0] * x;
    this.matrix[5] += this.matrix[3] * y;
  }
  scale(x: number, y: number): void {
    this.matrix[0] *= x;
    this.matrix[3] *= y;
  }
  rotate(): void {}
  beginPath(): void {
    this.pending = [];
  }
  closePath(): void {}
  moveTo(): void {}
  lineTo(): void {}
  arc(): void {}
  quadraticCurveTo(): void {}
  bezierCurveTo(): void {}
  rect(x: number, y: number, width: number, height: number): void {
    this.pending.push(this.box(x, y, width, height));
  }
  clip(): void {
    for (const box of this.pending) this.clips.push(box);
  }
  fill(): void {}
  stroke(): void {}
  setLineDash(): void {}
  drawImage(): void {}
  fillRect(x: number, y: number, width: number, height: number): void {
    this.rects.push({ ...this.box(x, y, width, height), fill: String(this.fillStyle) });
  }
  fillText(text: string, x: number, y: number): void {
    this.texts.push({ text, x: this.matrix[0] * x + this.matrix[4], y: this.matrix[3] * y + this.matrix[5], scale: this.matrix[0] });
  }
  measureText(text: string): { width: number } {
    const size = Number((/(\d+(?:\.\d+)?)px/.exec(this.font) || [])[1]) || 10;
    return { width: text.length * size * 0.5 };
  }
  private box(x: number, y: number, width: number, height: number): { x: number; y: number; width: number; height: number } {
    return { x: this.matrix[0] * x + this.matrix[4], y: this.matrix[3] * y + this.matrix[5], width: this.matrix[0] * width, height: this.matrix[3] * height };
  }
}

const asContext = (ctx: RecordingContext) => ctx as unknown as CanvasRenderingContext2D;
const near = (actual: number, expected: number, message: string, tolerance = 0.01) => assert.ok(Math.abs(actual - expected) <= tolerance, `${message}: ${actual} is not ${expected}`);

const CHART = (name = 'barChart') =>
  chartXml({
    head: title('Satışlar'),
    plot:
      group(name, '<c:barDir val="col"/><c:grouping val="clustered"/>', ser(0, { cat: strRef('Sayfa1!$A$1:$A$3', ['x', 'y', 'z']), val: numRef('Sayfa1!$B$1:$B$3', [1, 1, 1]), props: spPr(solid('00B050')) })) +
      catAx() +
      valAx('<c:majorGridlines/>', '<c:orientation val="minMax"/><c:max val="40"/><c:min val="0"/>'),
  });
const CELLS = sheetData([['Çay', 10], ['Kahve', 20], ['Süt', 40]]);

async function book(setup?: string, chart = CHART()): Promise<Workbook> {
  const bytes = await chartWorkbook({ sheet: CELLS, chartSheet: chart, chartSheetSetup: setup });
  return (await (await open(bytes)).workbook()) as Workbook;
}

const codeOf = (run: () => unknown): string | undefined => {
  try {
    run();
  } catch (error) {
    return error instanceof DocumentPrintError ? error.code : String(error);
  }
  return undefined;
};

test('a chart sheet is one page: landscape, the chart as large as the margins leave it', async () => {
  const workbook = await book();
  assert.equal(workbook.sheets[1].kind, 'chartsheet');
  const plan = planSheetPages(workbook, [1]);
  assert.equal(plan.pages.length, 1);
  assert.deepEqual(plan.sheets, [1]);
  const { layout, page } = plan.pages[0];
  // UNSURE: a chart sheet that says nothing of its paper lies on its side, as Excel makes a new one.
  assert.deepEqual([layout.paper, layout.landscape], [{ width: 1122.52, height: 793.7 }, true]);
  assert.ok(plan.pages[0].chart, 'the page knows its chart');
  // The margins of a new sheet: 0.7 inch at the sides, 0.75 above and below.
  near(page.x, 67.2, 'left margin');
  near(page.y, 72, 'top margin');
  near(page.width, 1122.52 - 134.4, 'the width between the margins');
  near(page.height, 793.7 - 144, 'the height between them');
  assert.equal(layout.scale, 1);
  assert.deepEqual(planSheetPages(workbook, [1], { defaultPaper: 1 }).pages[0].layout.paper, { width: 1056, height: 816 }, 'the paper of the language where the sheet names none');
});

test('a chart sheet follows its own page setup: paper, direction, margins, the number of its page', async () => {
  const workbook = await book('<pageMargins left="1" right="2" top="0.5" bottom="1.5" header="0.3" footer="0.3"/><pageSetup paperSize="1" orientation="portrait" useFirstPageNumber="1" firstPageNumber="7"/>');
  assert.deepEqual(workbook.sheets[1].pageSetup?.page, { paperSize: 1, orientation: 'portrait', useFirstPageNumber: true, firstPageNumber: 7 });
  const plan = planSheetPages(workbook, [1]);
  const { layout, page } = plan.pages[0];
  assert.deepEqual([layout.paper, layout.landscape], [{ width: 816, height: 1056 }, false]);
  assert.deepEqual([page.x, page.y, page.width, page.height], [96, 48, 816 - 96 - 192, 1056 - 48 - 144]);
  assert.equal(plan.pages[0].number, 7);
  const landscape = await book('<pageSetup orientation="landscape"/>');
  assert.equal(planSheetPages(landscape, [1]).pages[0].layout.landscape, true);
  const impossible = await book('<pageMargins left="9" right="9" top="9" bottom="9" header="0" footer="0"/>');
  const safe = planSheetPages(impossible, [1]).pages[0].page;
  assert.ok(safe.width > 100 && safe.height > 100, 'margins that leave no room are replaced by those of a new sheet');
});

test('chart sheets are printed in their place among the sheets; one whose chart is not drawn is left out', async () => {
  const workbook = await book();
  const all = planSheetPages(workbook, [0, 1]);
  assert.deepEqual(all.pages.map((page) => `${page.sheet}:${page.index}:${page.number}`), ['0:0:1', '1:0:2'], 'pages are numbered through the job');
  assert.equal(all.pages[0].chart, undefined, 'a worksheet page has no chart of its own');
  assert.deepEqual(planSheetPages(workbook, [1, 0, 1]).pages.map((page) => `${page.sheet}:${page.number}`), ['1:1', '0:2', '1:3'], 'the page of a chart sheet counts: what follows it has the next number');
  const surface = await book(undefined, CHART('surfaceChart'));
  assert.equal(codeOf(() => planSheetPages(surface, [1])), 'empty', 'a chart sheet that shows a note has nothing to print');
  assert.deepEqual(planSheetPages(surface, [0, 1]).sheets, [0]);
  assert.equal(codeOf(() => planSheetPages(workbook, [1], { maxPages: 1 })), undefined, 'one page fits a limit of one');
  assert.equal(codeOf(() => planSheetPages(workbook, [0, 1], { maxPages: 1 })), 'too-long');
});

test('the page of a chart sheet is white paper with the chart between its margins, from the cells as they are', async () => {
  const workbook = await book();
  const plan = planSheetPages(workbook, [1]);
  const ctx = new RecordingContext();
  // Twice the px of the paper.
  paintSheetPage(asContext(ctx), { workbook, job: plan.pages[0], total: 1, metrics: createSheetMetrics(workbook.sheets[0]), pixelWidth: 2245.04, now: new Date(2026, 0, 1) });
  assert.equal(ctx.rects[0].fill, '#ffffff');
  assert.ok(ctx.rects[0].x === 0 && ctx.rects[0].y === 0 && ctx.rects[0].width >= 2245.04 && ctx.rects[0].height >= 1587.4, 'the paper, all of it');
  const left = 67.2 * 2;
  const top = 72 * 2;
  const right = (1122.52 - 67.2) * 2;
  const bottom = (793.7 - 72) * 2;
  const frame = ctx.clips[0];
  near(frame.x, left, 'the chart is cut at the left margin');
  near(frame.y, top, 'at the top margin');
  near(frame.x + frame.width, right, 'at the right margin');
  near(frame.y + frame.height, bottom, 'and at the bottom margin');
  // The three columns, in the colour of the series, as high as the cells say: 10, 20 and 40 of 40.
  const columns = ctx.rects.filter((rect) => rect.fill === '#00B050');
  assert.equal(columns.length, 3);
  near(columns[2].height / columns[0].height, 4, 'the cells are what is printed, not what the file cached');
  for (const column of columns) assert.ok(column.x >= left && column.x + column.width <= right && column.y >= top && column.y + column.height <= bottom + 0.01, 'a column lies between the margins');
  const words = ctx.texts.map((call) => call.text);
  assert.ok(words.indexOf('Satışlar') >= 0 && words.indexOf('Kahve') >= 0, 'the title and the categories are printed');
  assert.ok(ctx.texts.every((call) => call.scale === 2), 'at the scale of the canvas');
  assert.ok(ctx.texts.every((call) => call.x >= left && call.x <= right && call.y >= top && call.y <= bottom), 'inside the margins');
});

test('the header and the footer of a chart sheet are printed with it', async () => {
  const workbook = await book('<headerFooter><oddHeader>&amp;C&amp;A</oddHeader><oddFooter>&amp;RSayfa &amp;P / &amp;N</oddFooter></headerFooter>');
  const plan = planSheetPages(workbook, [0, 1]);
  const ctx = new RecordingContext();
  paintSheetPage(asContext(ctx), { workbook, job: plan.pages[1], total: 2, metrics: createSheetMetrics(workbook.sheets[0]), pixelWidth: 1122.52, now: new Date(2026, 0, 1) });
  const words = ctx.texts.map((call) => call.text);
  assert.ok(words.indexOf('Grafik1') >= 0, 'the name of the sheet in the header');
  assert.ok(words.indexOf('Sayfa 2 / 2') >= 0, 'the number of the page in the footer');
});
